  toggle: () => <Toggle aria-label="Toggle bold"><Bold /></Toggle>,
  "toggle-group": () => <ToggleGroup defaultValue={["bold"]}><ToggleGroupItem value="bold" aria-label="Bold"><Bold /></ToggleGroupItem><ToggleGroupItem value="italic" aria-label="Italic"><Italic /></ToggleGroupItem><ToggleGroupItem value="underline" aria-label="Underline"><Underline /></ToggleGroupItem></ToggleGroup>,
  tooltip: () => <Tooltip><TooltipTrigger render={<Button size="icon" variant="outline" aria-label="Notifications" />}><Bell /></TooltipTrigger><TooltipContent>Notifications</TooltipContent></Tooltip>,
};

export const stockComponentDemoSlugs = Object.keys(demos).sort();

export function StockComponentDemo({ componentSlug }: { componentSlug: string }) {
  const renderDemo = demos[componentSlug];
  if (!renderDemo) {
    return <p className="text-sm text-muted-foreground">Demo unavailable.</p>;
  }
  return <>{renderDemo()}</>;
}
